d = assign['dimension_d']
n = assign['size_n']
if not isinstance(d, int) or not isinstance(n, int):
    return (False, None)  # wrong types
if d < 3 or n < 2:
    return (False, None)  # out of domain
# Compute the claimed optimal value:
# For n=2, any two consecutive blocks are collinear, hence every step counts.
# Path length is 2^d - 1 steps, so maximum count is 2^d - 1.
# For n >= 3, the generalized upper bound and construction yield n^{d-1} + 2.
if n == 2:
    answer = (2 ** d) - 1
else:
    answer = (n ** (d - 1)) + 2
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
